-- One-time legacy title import. Voting is intentionally retired.
insert into public.titles(id,title,type,format,description,poster_url,legacy_platform,added_by,created_at,metadata_source)
select id,title,type,format,description,poster_url,legacy_platform,added_by,created_at,metadata_source
from jsonb_to_recordset('[{"id":"monsters-of-god","title":"Monsters of God","type":"Documentary","format":null,"description":"Eric Goode follows the obsessive, high-stakes world of exotic reptile collecting and the illegal wildlife trade, where rare animals, huge money, smugglers, and law enforcement collide.","poster_url":"","legacy_platform":"HBO Max","added_by":null,"created_at":"2026-08-16T00:00:00Z","metadata_source":"legacy"},{"id":"breath-of-fire","title":"Breath of Fire","type":"Documentary","format":null,"description":"A revealing look at the rise of Kundalini yoga in the United States, the movement around Yogi Bhajan, and the complicated legacy surrounding one of its most prominent leaders.","poster_url":"","legacy_platform":"HBO Max","added_by":null,"created_at":"2026-08-16T00:00:00Z","metadata_source":"legacy"},{"id":"ufo-documentary","title":"Area 51: Aliens, UFOs, Bob Lazar & Advanced Technology","type":"Documentary","format":null,"description":"A short dive into Bob Lazar''s Area 51 claims, UFO sightings, alleged recovered craft, Element 115, government secrecy, and the advanced technology rumored to be hidden in the Nevada desert.","poster_url":"","legacy_platform":"Prime Video","added_by":null,"created_at":"2026-08-16T00:00:00Z","metadata_source":"legacy"},{"id":"i-am-chris-farley","title":"I Am Chris Farley","type":"Documentary","format":null,"description":"Friends, family, and fellow comedians remember Chris Farley''s life, enormous comic talent, unforgettable characters, and the person behind all that glorious physical comedy.","poster_url":"","legacy_platform":"Prime Video","added_by":null,"created_at":"2026-08-16T00:00:00Z","metadata_source":"legacy"},{"id":"behind-the-curve","title":"Behind the Curve","type":"Documentary","format":null,"description":"A funny, fascinating look inside the modern flat-Earth community, including the believers trying to prove their case and the experiments that do not always cooperate with the theory.","poster_url":"","legacy_platform":"Prime Video","added_by":null,"created_at":"2026-08-16T00:00:00Z","metadata_source":"legacy"},{"id":"cruella","title":"Cruella","type":"Movie","format":"film","description":"In 1970s punk-rock London, ambitious young designer Estella clashes with fashion legend Baroness von Hellman and begins transforming into the spectacularly rebellious Cruella de Vil.","poster_url":"","legacy_platform":"Disney+","added_by":null,"created_at":"2026-08-16T00:00:00Z","metadata_source":"legacy"},{"id":"futurama","title":"Futurama","type":"Series","format":"series","description":"Pizza delivery guy Philip J. Fry wakes up a thousand years in the future and joins the Planet Express crew for intergalactic deliveries, robot nonsense, aliens, romance, and beautifully nerdy science jokes.","poster_url":"","legacy_platform":"Disney+","added_by":null,"created_at":"2026-08-16T00:00:00Z","metadata_source":"legacy"},{"id":"always-sunny","title":"It''s Always Sunny in Philadelphia","type":"Series","format":"series","description":"Five wildly selfish owners of a struggling Philadelphia bar repeatedly hatch terrible plans, betray one another, and somehow make every possible situation much, much worse.","poster_url":"","legacy_platform":"Disney+","added_by":null,"created_at":"2026-08-16T00:00:00Z","metadata_source":"legacy"},{"id":"abbott-elementary","title":"Abbott Elementary","type":"Series","format":"series","description":"A group of dedicated teachers and one spectacularly self-confident principal navigate an underfunded Philadelphia public school while doing their best for the kids who keep them coming back.","poster_url":"","legacy_platform":"Disney+","added_by":null,"created_at":"2026-08-16T00:00:00Z","metadata_source":"legacy"},{"id":"custom-the-chris-farley-documentary-mutwtrbm","title":"The Chris Farley Documentary","type":"Documentary","format":null,"description":"Added by Parker. Family-added documentary ready for the CouchSloth vote.","poster_url":"","legacy_platform":"Family pick","added_by":"parker","created_at":"2026-10-04T14:22:15.440Z","metadata_source":"legacy"}]'::jsonb) as t(id text,title text,type text,format text,description text,poster_url text,legacy_platform text,added_by text,created_at timestamptz,metadata_source text)
on conflict(id) do nothing;

insert into public.watch_progress(profile_id,title_id)
select added_by,id from public.titles where added_by is not null and metadata_source='legacy'
on conflict(profile_id,title_id) do nothing;
